-- Synthetic versions of 4 actual ON DELETE SET NULL tables from live pg_constraint.
-- Production uses richer schema; this fixture tests FK relationship semantics.
create table public.analytics_events(
 id bigint generated by default as identity primary key,
 offer_id uuid references public.offers(id) on delete set null
);
create table public.attribution_events(
 id bigint generated by default as identity primary key,
 offer_id uuid references public.offers(id) on delete set null
);
create table public.user_feedback(
 id uuid primary key,
 offer_id uuid references public.offers(id) on delete set null
);
create table public.watch_events(
 id uuid primary key,
 offer_id uuid references public.offers(id) on delete set null
);
